namespace ghidra.app.plugin.core.label;









using docking;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.task;

public class LabelHistoryInputDialog : DialogComponentProvider {

	private JTextField inputField;
	private LabelHistoryTask task;
	private Program program;
	private PluginTool tool;

	public LabelHistoryInputDialog(PluginTool tool, Program program) : base("Label History Search", true)
    {
		this.program = program;
		this.tool = tool;

		addWorkPanel(buildMainPanel());
		addOKButton();
		addCancelButton();
		setHelpLocation(new HelpLocation(HelpTopics.LABEL, "Show_All_History"));
	}

	/* @Override */
	protected void cancelCallback() {
		close();
	}

	/* @Override */
	protected void okCallback() {
		string text = inputField.getText();
		if (text.length() == 0) {
			text = null;
		}
		task = new LabelHistoryTask(tool, program, text);
		task.addTaskListener(this);

		tool.execute(task, 250);
	}

	void showDialog() {
		clearStatusText();
		inputField.selectAll();
		tool.showDialog(this);
	}

	private JPanel buildMainPanel() {
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBorder(BorderFactory.createTitledBorder("Enter Symbol Name"));

		inputField = new JTextField(25);
		inputField.getAccessibleContext().setAccessibleName("Input");
		setFocusComponent(inputField);
		inputField.addActionListener(new _Anon_ActionListener_1());
		inputField.getDocument().addDocumentListener(new _Anon_DocumentListener_2());

		panel.add(inputField, BorderLayout.CENTER);
		panel.getAccessibleContext().setAccessibleName("Name Entry");
		JPanel outerPanel = new JPanel(new BorderLayout());
		outerPanel.setBorder(BorderFactory.createEmptyBorder(5, 5, 0, 5));
		outerPanel.add(panel, BorderLayout.CENTER);
		outerPanel.getAccessibleContext().setAccessibleName("Label History Input");
		return outerPanel;
	}

	/* @Override */
	public void taskCancelled(Task cancelTask) {
		taskCompleted(cancelTask);
	}

	/* @Override */
	public void taskCompleted(Task t) {
		if (!task.labelsFound()) {
			string matchStr = inputField.getText();
			if (matchStr.length() == 0) {
				setStatusText("No label history was found");
			}
			else {
				setStatusText("No matches were found for " + matchStr);
			}
		}
		else {
			close();
		}
	}


	internal class _Anon_ActionListener_1 : ActionListener
	{

			/* @Override */
			public void actionPerformed(ActionEvent e) {
				okCallback();
			}
		
	}


	internal class _Anon_DocumentListener_2 : DocumentListener
	{

			/* @Override */
			public void changedUpdate(DocumentEvent e) {
				clearStatusText();
			}

			/* @Override */
			public void insertUpdate(DocumentEvent e) {
				clearStatusText();
			}

			/* @Override */
			public void removeUpdate(DocumentEvent e) {
				clearStatusText();
			}
		
	}

}
